import{_ as o,C as n,o as e,c as s,a2 as l,b as i,w as r,a as d,E as g,a3 as E}from"./chunks/framework.BODD28Fk.js";const C="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",b=JSON.parse('{"title":"우편 라벨 관리","description":"","frontmatter":{},"headers":[],"relativePath":"notice/label.md","filePath":"notice/label.md","lastUpdated":1793459412000}'),B={name:"notice/label.md"};function A(c,t,m,h,u,p){const a=n("Mermaid");return e(),s("div",null,[t[1]||(t[1]=l('<h1 id="우편-라벨-관리" tabindex="-1">우편 라벨 관리 <a class="header-anchor" href="#우편-라벨-관리" aria-label="Permalink to &quot;우편 라벨 관리&quot;">​</a></h1><p>프로젝트 계약자들의 주소 정보를 바탕으로 규격 라벨지에 인쇄할 수 있도록 라벨 데이터를 생성하고 출력하는 화면입니다.</p><ul><li><strong>위치</strong>: <code>고객 고지 관리 &gt; 우편 라벨 관리</code></li></ul><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+C+'" alt="우편 라벨 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/label.png</code> 경로에 등록해 주세요.</em></p></div><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>고지서, 총회 책자, 안내문, 동의서 등의 우편물 발송 시 필요한 수신처 라벨 스티커를 표준 폼텍(Formtec) 라벨지 규격에 맞춰 손쉽게 출력할 수 있습니다. 차수·타입·동별 필터링은 물론, 실거주지 우선/주민등록지 전용 등 주소 기준 선택, 사용하다 남은 라벨지 재활용을 위한 인쇄 시작 위치(Offset) 지정, 수신자 맞춤 인쇄 옵션을 제공합니다.</p>',6)),(e(),i(E,null,{default:r(()=>[g(a,{id:"mermaid-24",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EB%8C%80%EC%83%81%20%EC%A1%B0%EA%B1%B4%20%EA%B2%80%EC%83%89%3Cbr%2F%3E(%EC%B0%A8%EC%88%98%C2%B7%ED%83%80%EC%9E%85%C2%B7%EB%8F%99%20%ED%95%84%ED%84%B0)%22%5D%20--%3E%20B%5B%222.%20%EB%9D%BC%EB%B2%A8%20%EB%B0%8F%20%EC%A3%BC%EC%86%8C%20%EC%98%B5%EC%85%98%20%EC%84%A4%EC%A0%95%3Cbr%2F%3E(%EC%9A%B0%ED%8E%B8%EC%86%A1%EB%B6%80%EC%A7%80%20%EC%9A%B0%EC%84%A0%C2%B7%EB%B0%94%EC%BD%94%EB%93%9C%20%EB%93%B1)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%EC%8B%9C%EC%9E%91%20%EC%B9%B8%20%EB%B2%88%ED%98%B8%20%EC%A7%80%EC%A0%95%3Cbr%2F%3E(%EB%82%A8%EC%9D%80%20%EB%9D%BC%EB%B2%A8%EC%A7%80%20%EC%9E%AC%ED%99%9C%EC%9A%A9%201~16)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20%EC%9D%B8%EC%87%84%20%EB%AF%B8%EB%A6%AC%EB%B3%B4%EA%B8%B0%3Cbr%2F%3E(%EC%8B%A4%EB%AC%BC%20%EB%B9%84%EC%9C%A8%20%EB%B0%B0%EC%B9%98%20%ED%99%95%EC%9D%B8)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20%EB%B8%8C%EB%9D%BC%EC%9A%B0%EC%A0%80%201%3A1%20%EC%9D%B8%EC%87%84%3Cbr%2F%3E(%EB%B0%B0%EC%9C%A8%20100%25%20%C2%B7%20%EC%97%AC%EB%B0%B1%20%EC%97%86%EC%9D%8C)%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>표준 라벨 규격 완벽 지원</strong>: 국내 우편 실무에서 가장 널리 사용되는 한국폼텍 표준 라벨지(Formtec 3107: 99.1 × 38.1 mm, A4당 16칸, 2열 8행) 기본 지원</li><li><strong>인쇄 시작 위치(오프셋) 지정</strong>: 이미 몇 칸을 사용하고 남은 라벨 용지를 알뜰하게 재활용할 수 있도록 첫 번째 라벨 인쇄 위치(1번~16번) 지정 가능</li><li><strong>실무 맞춤형 주소지 선택 기준 지원</strong>: <ul><li><code>우편송부지 우선</code>: 우편송부지가 등록되어 있으면 우편송부지를, 미등록 시 주민등록상 주소를 자동 적용</li><li><code>우편송부지 전용</code>: 우편송부지가 별도로 등록된 계약자만 선별하여 출력</li><li><code>주민등록지 전용</code>: 우편송부지 등록 여부와 상관없이 계약자의 주민등록상 기본 주소만 출력</li></ul></li><li><strong>수신처 맞춤 인쇄 옵션</strong>: 우편번호 바코드 서식 표시, 계약자 성명 뒤 존칭(&#39;귀하&#39;) 출력, 계약 동·호수(또는 일련번호) 표기 여부 토글</li><li><strong>대용량 데이터 최적화 페이징 및 선택</strong>: 수천 명의 계약자 데이터를 쾌적하게 조회할 수 있도록 페이지당 표시 개수(30/50/100/200건) 설정, 현재 페이지 선택 및 검색 전체 대상 일괄 선택 지원</li><li><strong>외부 프로그램 없는 브라우저 1:1 다이렉트 인쇄</strong>: 라벨 규격에 최적화된 인쇄 스타일시트가 적용되어 별도의 전용 소프트웨어 설치 없이 브라우저 인쇄(Ctrl+P / Cmd+P)로 오차 없이 실물 출력</li></ul><h2 id="화면-구성-및-실무-가이드" tabindex="-1">화면 구성 및 실무 가이드 <a class="header-anchor" href="#화면-구성-및-실무-가이드" aria-label="Permalink to &quot;화면 구성 및 실무 가이드&quot;">​</a></h2><h3 id="_1-필터-및-인쇄-환경-설정-상단" tabindex="-1">1. 필터 및 인쇄 환경 설정 (상단) <a class="header-anchor" href="#_1-필터-및-인쇄-환경-설정-상단" aria-label="Permalink to &quot;1. 필터 및 인쇄 환경 설정 (상단)&quot;">​</a></h3><p>라벨을 출력할 계약자 조건과 라벨 용지의 물리적 인쇄 옵션을 지정합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">설정 항목</th><th style="text-align:center;">구분</th><th style="text-align:left;">상세 설명 및 실무 팁</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>차수 / 타입 / 동</strong></td><td style="text-align:center;">필터</td><td style="text-align:left;">특정 차수, 타입, 동별로 우편물을 발송할 대상 계약자를 선별합니다.</td></tr><tr><td style="text-align:left;"><strong>라벨 규격</strong></td><td style="text-align:center;">인쇄 설정</td><td style="text-align:left;">출력할 라벨지 제품 규격입니다. (Formtec 3107: 99.1 × 38.1 mm, A4 1장당 16칸)</td></tr><tr><td style="text-align:left;"><strong>인쇄 시작 위치</strong></td><td style="text-align:center;">인쇄 설정</td><td style="text-align:left;">라벨지 내 첫 번째 데이터가 인쇄될 칸 번호(1~16번)를 지정합니다. 쓰다 남은 라벨 용지를 재활용할 때 필수적입니다.</td></tr><tr><td style="text-align:left;"><strong>주소지 선택</strong></td><td style="text-align:center;">데이터 기준</td><td style="text-align:left;"><code>우편송부지 우선</code>, <code>우편송부지 전용</code>, <code>주민등록지 전용</code> 중 우편물 발송 목적에 맞게 선택합니다.</td></tr><tr><td style="text-align:left;"><strong>바코드 표시</strong></td><td style="text-align:center;">인쇄 옵션</td><td style="text-align:left;">우편번호(5자리) 영문 바코드 서식을 라벨 하단에 함께 출력할지 여부를 설정합니다.</td></tr><tr><td style="text-align:left;"><strong>&#39;귀하&#39; 표시</strong></td><td style="text-align:center;">인쇄 옵션</td><td style="text-align:left;">수신자 성명 뒤에 존칭(&#39;귀하&#39;)을 자동으로 붙여 출력할지 여부를 설정합니다.</td></tr><tr><td style="text-align:left;"><strong>동·호수 표시</strong></td><td style="text-align:center;">인쇄 옵션</td><td style="text-align:left;">라벨 우측 상단에 계약 동·호수(동호수 미배정 시 계약 일련번호)를 함께 표기할지 여부를 설정합니다.</td></tr></tbody></table><h3 id="_2-계약자-목록-및-선택-데이터-테이블" tabindex="-1">2. 계약자 목록 및 선택 (데이터 테이블) <a class="header-anchor" href="#_2-계약자-목록-및-선택-데이터-테이블" aria-label="Permalink to &quot;2. 계약자 목록 및 선택 (데이터 테이블)&quot;">​</a></h3><p>조회된 계약자 목록에서 실제 라벨을 출력할 대상자를 지정합니다.</p><ul><li><strong>테이블 표시 항목</strong>: 선택 체크박스, 일련번호, 계약자명, 동호수, 우편번호, 주소 및 상세주소, 비고(우편송부지 구분 등)</li><li><strong>페이징 제어</strong>: 하단 페이지네이션을 통해 대용량 계약 데이터도 부드럽게 조회할 수 있습니다. (30, 50, 100, 200건 단위)</li><li><strong>선택 제어 기능</strong>: <ul><li><strong>현재 페이지 선택</strong>: 테이블 상단 헤더 체크박스를 클릭하여 현재 페이지에 보이는 계약자들만 선택합니다.</li><li><strong>검색 결과 전체 선택</strong>: 상단의 [검색 결과 전체 선택] 버튼을 누르면 필터 조건에 부합하는 모든 대상 계약자가 한 번에 인쇄 대상으로 선택됩니다.</li></ul></li></ul><h3 id="_3-인쇄-미리보기-및-라벨-출력" tabindex="-1">3. 인쇄 미리보기 및 라벨 출력 <a class="header-anchor" href="#_3-인쇄-미리보기-및-라벨-출력" aria-label="Permalink to &quot;3. 인쇄 미리보기 및 라벨 출력&quot;">​</a></h3><p>실제 라벨지에 인쇄하기 전 화면에서 레이아웃을 확인하고 인쇄를 실행합니다.</p><ul><li><strong>인쇄 미리보기 버튼</strong>: 현재 선택된 계약자 수와 지정한 &#39;인쇄 시작 위치&#39;가 반영된 실물 비율의 라벨지 미리보기 창을 엽니다.</li><li><strong>라벨 인쇄 (Ctrl+P / Cmd+P)</strong>: [라벨 인쇄] 버튼을 누르면 브라우저의 표준 인쇄 대화상자가 호출됩니다.</li></ul><h2 id="💡-브라우저-인쇄-필수-설정-및-업무-팁" tabindex="-1">💡 브라우저 인쇄 필수 설정 및 업무 팁 <a class="header-anchor" href="#💡-브라우저-인쇄-필수-설정-및-업무-팁" aria-label="Permalink to &quot;💡 브라우저 인쇄 필수 설정 및 업무 팁&quot;">​</a></h2><p>라벨지는 인쇄 여백이나 배율이 1mm만 틀어져도 칸을 벗어나 용지를 낭비하게 됩니다. 인쇄 대화상자에서 아래 <strong>3대 설정</strong>을 반드시 확인하세요.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>브라우저 인쇄 대화상자 3대 필수 설정 (오차 방지)</strong></p><ol><li><strong>배율 (Scale)</strong>: 반드시 **<code>100%</code> (기본값)**으로 설정하세요. (<em>&#39;용지에 맞춤&#39;을 선택하면 축소되어 라벨 칼선이 맞지 않습니다.</em>)</li><li><strong>여백 (Margins)</strong>: 반드시 **<code>없음 (None)</code>**으로 지정하세요.</li><li><strong>머리글 및 바닥글 (Headers and Footers)</strong>: 체크를 <strong>해제</strong>하세요. (<em>체크되어 있으면 상단/하단에 날짜나 웹 URL이 인쇄되어 첫 번째와 마지막 라벨이 훼손됩니다.</em>)</li></ol></div><ul><li><strong>남은 라벨지 알뜰 재활용</strong>: 이전 우편 발송 후 상단 4칸을 사용하고 5번째 칸부터 남아있는 라벨지가 있다면, <strong>&#39;인쇄 시작 위치&#39;를 <code>5</code>로 지정</strong>하세요. 첫 번째 대상자가 정확히 5번째 칸부터 인쇄되므로 버리는 라벨지 없이 100% 활용할 수 있습니다.</li><li><strong>우편번호 누락 점검</strong>: 수신 주소에 5자리 우편번호가 등록되지 않은 계약자는 우편번호 영역이 비어 있게 됩니다. 대량 발송 전 [계약 목록 관리]에서 우편번호 누락 건이 없는지 미리 점검하세요.</li><li><strong>테스트 용지 인쇄</strong>: 라벨지 스티커 용지는 일반 복사용지보다 단가가 높습니다. 먼저 <strong>일반 A4 복사용지에 1장만 인쇄</strong>한 뒤, 실물 라벨지에 겹쳐서 빛에 비춰보면 칼선과 정확히 일치하는지 안전하게 검증할 수 있습니다.</li></ul>',16))])}const x=o(B,[["render",A]]);export{b as __pageData,x as default};
